package com.exelynt.booking.controller; import com.exelynt.booking.dto.*;import com.exelynt.booking.service.ResourceService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/resources") public class ResourceController {private final ResourceService s;public ResourceController(ResourceService x){s=x;}@GetMapping public List<ResourceResponse> list(){return s.all();}@GetMapping("/{id}") public ResourceResponse get(@PathVariable Long id){return s.one(id);}@PostMapping public ResponseEntity<ResourceResponse> create(@Valid @RequestBody ResourceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@PutMapping("/{id}") public ResourceResponse update(@PathVariable Long id,@Valid @RequestBody ResourceRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.delete(id);}}
